function baseImages(dockerfile) {
  return dockerfile
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => /^from\s/i.test(line))
    .map((line) => line.split(/\s+/)[1]);
}

def missing_ignores(lines, required):
    present = {line.strip().strip("/") for line in lines if line.strip() and not line.strip().startswith("#")}
    return [r for r in required if r not in present]

function missingKeys(envText, required) {
  const values = {};
  for (const raw of envText.split("\n")) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const eq = line.indexOf("=");
    if (eq < 1) continue;
    values[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
  }
  return required.filter((key) => !values[key]);
}

def layer_count(dockerfile):
    count = 0
    for line in dockerfile.split("\n"):
        if not line or line[0].isspace() or line.startswith("#"):
            continue
        if line.split()[0].upper() in ("RUN", "COPY", "ADD"):
            count += 1
    return count

function toExecForm(command) {
  const parts = command.trim().split(/\s+/).filter(Boolean);
  return JSON.stringify(parts);
}

