coding.referenceSolution:
def lint(dockerfile):
    warnings = set()
    stages = set()
    has_user = False
    for raw in dockerfile.split("\n"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        op = parts[0].upper()
        if op == "FROM":
            image = parts[1]
            if image != "scratch" and image not in stages:
                name = image.split("/")[-1]
                if ":" not in name or name.endswith(":latest"):
                    warnings.add("unpinned-base")
            if len(parts) >= 4 and parts[2].upper() == "AS":
                stages.add(parts[3])
        elif op == "ADD":
            warnings.add("uses-add")
        elif op == "USER":
            has_user = True
    if not has_user:
        warnings.add("no-user")
    return sorted(warnings)

