function stagesToBuild(stages, target) {
  const index = stages.findIndex((s) => s.name === target);
  return stages.slice(0, index + 1).map((s) => s.name);
}

coding.referenceSolution:
function stagesToBuild(stages, target) {
  const byName = new Map(stages.map((s) => [s.name, s]));
  if (!byName.has(target)) return [];
  const needed = new Set();
  let current = byName.get(target);
  while (current) {
    needed.add(current.name);
    current = byName.get(current.from);
  }
  return stages.filter((s) => needed.has(s.name)).map((s) => s.name);
}

def release_tags(version):
    version = version.lstrip("v")
    if "-" in version:
        return [version]
    major, minor, _patch = version.split(".")
    return [version, f"{major}.{minor}", major, "latest"]
